// Package exceltest validates xlsx workbooks generated by the atscale-utils
// generate-excel-from-namespace command using the excelize library as the
// reference parser. Tests cover both positive (valid inputs) and negative
// (edge-case / bad inputs) scenarios.
//
// Run from this directory:
//
//	go test -v ./...
package exceltest

import (
	"archive/zip"
	"bytes"
	"encoding/xml"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	excelize "github.com/xuri/excelize/v2"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// ---------------------------------------------------------------------------
// Test cache: generate each fixture once, share across all tests
// ---------------------------------------------------------------------------

// fixtureCache maps nsYAML → *fixtureEntry (sync.Once + result).
// Each unique fixture is generated exactly once even under t.Parallel().
var (
	fixtureCache    sync.Map   // map[string]*fixtureEntry
	fixtureCacheDir string     // package-level temp dir, owned by TestMain
)

type fixtureEntry struct {
	once sync.Once
	path string
}

// TestMain creates the shared temp dir, pre-builds the CLI once, runs the
// suite, then cleans up.  Building once here prevents concurrent npm-run-build
// invocations (one per parallel test) from corrupting the dist/ directory.
func TestMain(m *testing.M) {
	var err error
	fixtureCacheDir, err = os.MkdirTemp("", "exceltest-cache-*")
	if err != nil {
		panic(err)
	}

	// Build once up-front; individual CLI invocations will skip the build step.
	buildCmd := exec.Command("npm", "run", "build")
	buildCmd.Dir = projectRoot
	if out, err := buildCmd.CombinedOutput(); err != nil {
		panic(fmt.Sprintf("pre-test npm run build failed: %v\n%s", err, out))
	}
	// Signal to atscale-utils that the build is already up-to-date.
	os.Setenv("ATSCALE_SKIP_BUILD", "1")

	code := m.Run()
	_ = os.RemoveAll(fixtureCacheDir)
	os.Exit(code)
}

