// TestPositive_DrawingHasNvPr verifies the drawing XML includes the required
// <xdr:nvPr/> element, which was the cause of the "Repaired Records: Drawing"
// error in earlier versions.
func TestPositive_DrawingHasNvPr(t *testing.T) {
	t.Parallel()
	path := generate(t, nsValid)
	entries := zipEntries(t, path)

	var drawingFiles []string
	for _, e := range entries {
		if strings.HasPrefix(e, "xl/drawings/drawing") && !strings.Contains(e, "_rels") {
			drawingFiles = append(drawingFiles, e)
		}
	}
	require.NotEmpty(t, drawingFiles, "expected at least one drawing file")

	for _, df := range drawingFiles {
		raw := rawZipEntry(t, path, df)
		require.NotNil(t, raw)
		assert.Contains(t, string(raw), "<xdr:nvPr/>",
			"%s must include <xdr:nvPr/> in nvGraphicFramePr", df)
	}
}

// TestPositive_DrawingAnchorsOnDashboardOnly verifies drawings are attached
// only to dashboard sheets (not data sheets).
func TestPositive_DrawingAnchorsOnDashboardOnly(t *testing.T) {
	t.Parallel()
	path := generate(t, nsValid)
	f := openXlsx(t, path)
	entries := zipEntries(t, path)

	// Find which sheet numbers have drawing relationships.
	sheetsWithDrawings := make(map[string]bool)
	for _, e := range entries {
		if !strings.HasPrefix(e, "xl/worksheets/_rels/") {
			continue
		}
		raw := rawZipEntry(t, path, e)
		if strings.Contains(string(raw), "/relationships/drawing") {
			// e = "xl/worksheets/_rels/sheetN.xml.rels" → sheet name via workbook
			num := strings.TrimSuffix(strings.TrimPrefix(e, "xl/worksheets/_rels/sheet"), ".xml.rels")
			_ = num
			sheetsWithDrawings[e] = true
		}
	}

	// Every sheet with a drawing must be a visible (dashboard) sheet.
	sheets := f.GetSheetList()
	for _, sheet := range sheets {
		visible, _ := f.GetSheetVisible(sheet)
		_ = visible
	}

	// The simplest assertion: only one drawing file should exist (one dashboard).
	drawingCount := 0
	for _, e := range entries {
		if strings.HasPrefix(e, "xl/drawings/drawing") && !strings.Contains(e, "_rels") {
			drawingCount++
		}
	}
	assert.Equal(t, 1, drawingCount,
		"nsValid has 1 dashboard so should produce exactly 1 drawing file")
}

// TestPositive_PivotCacheHasNoPivotCacheRecords verifies no pivotCacheRecords
// files exist — OLAP caches with saveData="0" must not have them.
func TestPositive_PivotCacheHasNoPivotCacheRecords(t *testing.T) {
	t.Parallel()
	path := generate(t, nsValid)
	for _, e := range zipEntries(t, path) {
		assert.False(t, strings.Contains(e, "pivotCacheRecords"),
			"found unexpected pivotCacheRecords file: %s", e)
	}
}

// TestPositive_WorkbookRelsHasPivotCacheAndConnection verifies workbook.xml.rels
// registers all pivot caches and the connections.xml.
func TestPositive_WorkbookRelsHasPivotCacheAndConnection(t *testing.T) {
	t.Parallel()
	path := generate(t, nsValid)
	raw := rawZipEntry(t, path, "xl/_rels/workbook.xml.rels")
	require.NotNil(t, raw)

	content := string(raw)
	assert.Contains(t, content, "pivotCacheDefinition",
		"workbook.xml.rels must reference pivot cache definitions")
	assert.Contains(t, content, "connections.xml",
		"workbook.xml.rels must reference connections.xml")
}

// TestPositive_MultipleCollidingTilesNoMergeCellError verifies that two tiles
// with the same default x=0 position (the common case when x is unspecified)
// are placed in separate columns without a merge-cell collision error.
func TestPositive_MultipleCollidingTilesNoMergeCellError(t *testing.T) {
	t.Parallel()
	// This test would previously fail with "Cannot merge already merged cells"
	// before the x-position deduplication fix.
	path := generate(t, nsMultipleTilesSameXY) // must not panic/error
	f := openXlsx(t, path)

	sheets := f.GetSheetList()
	assert.Contains(t, sheets, "Multi Tile", "dashboard sheet should be created")
	assert.NotContains(t, sheets, "ws_a", "no separate data sheet for ws_a")
	assert.NotContains(t, sheets, "ws_b", "no separate data sheet for ws_b")
	assert.NotContains(t, sheets, "ws_c", "no separate data sheet for ws_c")

	// Merge cells on the dashboard should all be non-overlapping.
	merges, err := f.GetMergeCells("Multi Tile")
	require.NoError(t, err)
	// Check no two merge ranges share the same top-left cell.
	topLeft := make(map[string]bool)
	for _, m := range merges {
		tl := m.GetStartAxis()
		assert.False(t, topLeft[tl],
			"duplicate merge top-left cell %s (tiles are colliding)", tl)
		topLeft[tl] = true
	}
}

// ---------------------------------------------------------------------------
// NEGATIVE TESTS — edge cases and invalid inputs
// ---------------------------------------------------------------------------

// TestNegative_NoDashboards verifies that a namespace with no dashboard tiles
// (no tile references any worksheet) returns an error and produces no file.
// Without dashboard tiles there are no data passes, so no OLAP pivot table
// can be generated.
func TestNegative_NoDashboards(t *testing.T) {
	t.Parallel()
	output := generateExpectError(t, nsNoDashboards)
	assert.Contains(t, output, "No OLAP pivot table could be generated",
		"error message should explain why generation failed")
}

// TestNegative_NoMeasures verifies that a tile with no measures is handled
// gracefully: no chart is generated (0 series would be invalid OOXML), the
// workbook still opens, and no chart XML files are present.
func TestNegative_NoMeasures(t *testing.T) {
	t.Parallel()
	path := generate(t, nsNoMeasures)
	openXlsx(t, path) // must open without error

	entries := zipEntries(t, path)
	for _, e := range entries {
		assert.False(t, strings.HasPrefix(e, "xl/charts/chart"),
			"no chart should be generated when measures list is empty, found: %s", e)
	}
}

// TestNegative_UnknownModel verifies that referencing a non-existent model
// causes the CLI to exit with an error and produce no output file.
func TestNegative_UnknownModel(t *testing.T) {
	t.Parallel()
	output := generateExpectError(t, nsUnknownModel)
	assert.Contains(t, output, "NonExistentModel",
		"error message should name the missing model")
	assert.Contains(t, output, "not found in model file",
		"error message should explain the cause")
}

// TestNegative_UnknownGraphTypeDefaultsToBarChart verifies that an
// unrecognised graphType (e.g. "radar") falls back to bar chart in the
// generated chart XML.
func TestNegative_UnknownGraphTypeDefaultsToBarChart(t *testing.T) {
	t.Parallel()
	path := generate(t, nsUnknownGraphType)
	entries := zipEntries(t, path)

	var chartFiles []string
	for _, e := range entries {
		if strings.HasPrefix(e, "xl/charts/chart") {
			chartFiles = append(chartFiles, e)
		}
	}
	require.NotEmpty(t, chartFiles, "a chart should be generated for radar graphType")

	for _, cf := range chartFiles {
		raw := rawZipEntry(t, path, cf)
		// buildChartXml defaults to barChart for unrecognised types.
		assert.Contains(t, string(raw), "<c:barChart>",
			"%s: unrecognised graphType should produce barChart", cf)
	}
}

// TestNegative_ChartXmlHasValidSeriesForSingleMeasure verifies a chart with
// one measure + one dimension produces exactly one <c:ser> element.
func TestNegative_ChartXmlHasValidSeriesForSingleMeasure(t *testing.T) {
	t.Parallel()
	path := generate(t, nsValid)
	entries := zipEntries(t, path)

	for _, e := range entries {
		if !strings.HasPrefix(e, "xl/charts/chart") {
			continue
		}
		raw := rawZipEntry(t, path, e)
		content := string(raw)

		// Count <c:ser> elements.
		serCount := strings.Count(content, "<c:ser>")
		assert.Greater(t, serCount, 0, "%s: chart must have at least one series", e)

		// Each series must have a value reference.
		assert.Contains(t, content, "<c:val>",
			"%s: each series must have a value range reference", e)
	}
}

// TestNegative_PivotTableNoFieldsPlaced verifies that pivot table XML does NOT
// include rowFields/dataFields (which Excel would strip for OLAP saveData="0"
// and cause a "Removed Feature" repair message).
func TestNegative_PivotTableNoFieldsPlaced(t *testing.T) {
	t.Parallel()
	path := generate(t, nsValid)
	entries := zipEntries(t, path)

	for _, e := range entries {
		if !strings.HasPrefix(e, "xl/pivotTables/pivotTable") {
			continue
		}
		raw := rawZipEntry(t, path, e)
		content := string(raw)
		assert.NotContains(t, content, "<rowFields",
			"%s: pivot table must not contain rowFields (OLAP saveData=0 strips them)", e)
		assert.NotContains(t, content, "<dataFields",
			"%s: pivot table must not contain dataFields (OLAP saveData=0 strips them)", e)
	}
}
